{* Code generated by packages/kit-compose/src/server-organisms.ts from packages/compose-gen/specs (compose-gen organism emitters on kit-compose). DO NOT EDIT.
    Source: packages/compose-gen/specs/organisms/option-chips.json
    One choice as a radio group drawn as chips: a fieldset with role radiogroup named by its legend, one radio per option (the first checked), the name and an optional price or note. Static markup.
    Props (p): name, legend, options, extra, layout. *}
{var $v_name = ($p['name'] ?? null)}
{var $v_legend = ($p['legend'] ?? null)}
{var $v_options = ($p['options'] ?? null)}
{var $v_extra = ($p['extra'] ?? 'none')}
{var $v_layout = ($p['layout'] ?? 'wrap')}
{capture $c_8}
  {capture $c_1}
    {=og_text($v_legend)}
  {/capture}
  {=og_include('compose/Legend.latte', ['size' => 'sm', 'class' => 'mb-2', 'attrs' => og_attrs(['id', og_tpl('{0}-legend', [$v_name])]), 'children' => (string) $c_1])|noescape}
  {capture $c_7}
    {foreach og_l($v_options) as $v_o}
      {var $v_i = $iterator->counter0}
      {capture $c_6}
        {capture $c_3}
          {=og_include('compose/Radio.latte', ['name' => og_s($v_name), 'value' => og_s(og_get($v_o, ['id'])), 'checked' => og_t(og_eq($v_i, 0))])|noescape}
          {capture $c_2}
            {=og_text(og_get($v_o, ['name']))}
          {/capture}
          {=og_include('compose/Inline.latte', ['children' => (string) $c_2])|noescape}
        {/capture}
        {=og_include('compose/Inline.latte', ['class' => 'flex items-center gap-2', 'children' => (string) $c_3])|noescape}
        {if og_t(og_eq($v_extra, 'price'))}
          {capture $c_4}
            {=og_text(og_money(og_get($v_o, ['price']), og_get($v_o, ['currency'])))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'text-muted-foreground', 'children' => (string) $c_4])|noescape}
        {/if}
        {if og_t(og_eq($v_extra, 'note'))}
          {capture $c_5}
            {=og_text(og_get($v_o, ['note']))}
          {/capture}
          {=og_include('compose/Inline.latte', ['class' => 'text-muted-foreground', 'children' => (string) $c_5])|noescape}
        {/if}
      {/capture}
      {=og_include('compose/Label.latte', ['class' => og_s(og_cnv(['flex items-center gap-2 rounded px-4 py-2 text-sm inset-ring inset-ring-border has-checked:bg-muted has-checked:inset-ring-foreground', (og_t(og_eq($v_layout, 'column')) ? 'justify-between' : '')])), 'attrs' => og_attrs(['data-testid', 'option']), 'children' => (string) $c_6])|noescape}
    {/foreach}
  {/capture}
  {=og_include('compose/Box.latte', ['class' => og_s((og_t(og_eq($v_layout, 'column')) ? 'flex flex-col gap-2' : 'flex flex-wrap gap-2')), 'children' => (string) $c_7])|noescape}
{/capture}
{=og_include('compose/Fieldset.latte', ['class' => 'flex flex-col gap-2', 'attrs' => og_attrs(['role', 'radiogroup', 'aria-labelledby', og_tpl('{0}-legend', [$v_name]), 'data-testid', 'option-group']), 'children' => (string) $c_8])|noescape}
